import type { ImageName } from "../../data/content";

type Props = {
  name: ImageName;
  alt: string;
  className?: string;
  /** Approximate rendered width, for the browser's srcset pick. */
  sizes?: string;
  eager?: boolean;
};

/** 16:9 artwork from public/img (generated by `npm run images`). */
export function Banner({ name, alt, className = "", sizes = "(min-width: 1024px) 600px, 100vw", eager }: Props) {
  return (
    <img
      src={`/img/${name}-1600.webp`}
      srcSet={`/img/${name}-800.webp 800w, /img/${name}-1600.webp 1600w`}
      sizes={sizes}
      width={1672}
      height={941}
      alt={alt}
      loading={eager ? "eager" : "lazy"}
      decoding="async"
      className={`block h-auto w-full rounded-3xl border border-line shadow-[0_30px_80px_-30px_rgb(178_60_255/0.45)] ${className}`}
    />
  );
}
